types:
export interface CabSelectOption {
  /** Value emitted through `v-model`. */
  value: string
  /** Visible option text (also used for typeahead). */
  label: string
  /** Disabled options are shown but cannot be chosen or reached with the keyboard. */
  disabled?: boolean
}

export interface CabTab {
  /** Stable id used as the `v-model` value. */
  id: string
  /** Visible tab text. */
  label: string
  /** Disabled tabs are skipped by the arrow keys and cannot be selected. */
  disabled?: boolean
}
